mapper.select:
SELECT * FROM ( SELECT s.supplier_code AS supplierCode, s.supplier_name AS supplierName, s.contact, s.phone, COALESCE(order_counts.cnt, 0) AS orderCount, COALESCE(order_amounts.amt, 0) AS orderAmount, COALESCE(in_amounts.amt, 0) AS inAmount, COALESCE(return_amounts.amt, 0) AS returnAmount, COALESCE(in_amounts.amt, 0) - COALESCE(return_amounts.amt, 0) AS netPurchase, COALESCE(in_amounts.amt, 0) - COALESCE(paid_totals.amt, 0) AS apAmount, COALESCE(paid_totals.amt, 0) AS paidAmount, CASE WHEN COALESCE(in_amounts.amt, 0) > 0 THEN ROUND((COALESCE(paid_totals.amt, 0) / in_amounts.amt) * 100, 2) ELSE 0 END AS paymentRate, COALESCE(avg_prices.price, 0) AS avgPrice, last_order_dates.max_date AS lastOrderDate FROM wms_supplier s
INNER JOIN (SELECT id FROM wms_supplier WHERE id IN
#{id}
) filtered_suppliers ON s.id = filtered_suppliers.id
LEFT JOIN ( SELECT supplier_id, COUNT(*) AS cnt, SUM(total_amount) AS amt FROM wms_purchase_order WHERE del_flag = '0'
AND order_date BETWEEN #{startDate} AND #{endDate}
AND order_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND supplier_id IN
#{id}
GROUP BY supplier_id ) order_counts ON s.id = order_counts.supplier_id LEFT JOIN ( SELECT supplier_id, SUM(total_amount) AS amt FROM wms_purchase_order WHERE del_flag = '0'
AND order_date BETWEEN #{startDate} AND #{endDate}
AND order_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND supplier_id IN
#{id}
GROUP BY supplier_id ) order_amounts ON s.id = order_amounts.supplier_id LEFT JOIN ( SELECT supplier_id, SUM(total_amount) AS amt FROM wms_purchase_in WHERE del_flag = '0' AND status = '1'
AND in_date BETWEEN #{startDate} AND #{endDate}
AND in_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND supplier_id IN
#{id}
GROUP BY supplier_id ) in_amounts ON s.id = in_amounts.supplier_id LEFT JOIN ( SELECT supplier_id, SUM(total_amount) AS amt FROM wms_purchase_return WHERE del_flag = '0' AND status = '1'
AND return_date BETWEEN #{startDate} AND #{endDate}
AND return_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND supplier_id IN
#{id}
GROUP BY supplier_id ) return_amounts ON s.id = return_amounts.supplier_id LEFT JOIN ( SELECT supplier_id, SUM(paid_amount) AS amt FROM wms_purchase_in WHERE del_flag = '0' AND status = '1'
AND in_date BETWEEN #{startDate} AND #{endDate}
AND in_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND supplier_id IN
#{id}
GROUP BY supplier_id ) paid_totals ON s.id = paid_totals.supplier_id LEFT JOIN ( SELECT pi.supplier_id, AVG(pii.price) AS price FROM wms_purchase_in_item pii INNER JOIN wms_purchase_in pi ON pii.in_id = pi.id WHERE pi.del_flag = '0' AND pi.status = '1'
AND pi.in_date BETWEEN #{startDate} AND #{endDate}
AND pi.in_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
AND pi.supplier_id IN
#{id}
GROUP BY pi.supplier_id ) avg_prices ON s.id = avg_prices.supplier_id LEFT JOIN ( SELECT supplier_id, MAX(order_date) AS max_date FROM wms_purchase_order WHERE del_flag = '0' GROUP BY supplier_id ) last_order_dates ON s.id = last_order_dates.supplier_id WHERE s.del_flag = '0' ) t WHERE orderAmount > 0 OR inAmount > 0 ORDER BY netPurchase DESC
